 Share widely and freely. 15','c06cb2d73e00d6efb369c39a508f6534bade96ab3f6eb327f8970cd01b0bba9d','Magistrates Courts Act','General','[-0.041002117,0.036978465,0.024297627,-0.08158248,-0.028798643,-0.016004149,0.0146263195,-0.040241856,0.002445866,0.106673375,0.09328479,0.02060477,0.01951748,-0.09379029,0.0032224192,-0.062182467,0.02932391,-0.017965553,-0.09306617,0.00781481,0.10366173,0.022940988,0.040292326,-0.028660301,-0.0997417,0.017638747,-0.026292251,-0.052349262,0.014409295,-0.028264564,0.013433154,-0.022510333,0.03989683,0.025764303,-0.07753158,0.0050612404,0.0308812,-0.025623271,0.06126886,-0.06969998,0.07923473,-0.041566882,0.03505234,-0.099145144,0.041124303,0.009731403,-4.1899024E-4,0.038550172,-0.05759849,-0.05461311,-0.053922925,-0.09179124,-0.045500673,0.04012929,-0.08761899,-0.012451695,-0.017844338,-0.07020018,0.056859147,0.017230963,-0.027076958,0.05366483,-0.027622227,0.03381759,0.008399289,-0.12360246,0.039085176,-0.023325663,0.061416004,0.0035469162,0.13823779,-0.061147135,-0.008109433,-0.019840172,-0.14079978,0.05534066,0.024453582,-0.038980097,-0.017349241,-0.11159517,0.06933394,0.070170775,0.10866552,0.0061696447,0.052376576,-0.057618886,-0.05099083,-0.011277347,0.10934098,-0.057911977,0.038563713,-0.0051954254,-0.03625131,0.0010326054,0.014845559,-0.011432782,0.045500435,0.05525011,-0.0464095,0.031845484,0.03615966,-0.05518375,-0.11055011,-0.013916722,0.05751785,0.03927668,0.023523329,-0.008996719,-0.019508231,-0.0030548053,-0.012792016,0.04805011,-0.028060695,0.0029790886,0.04159507,1.866454E-4,0.0037378029,0.017869323,-0.033179663,-0.035223145,-0.032353986,0.005740326,0.0040288623,-0.108947024,0.0014841161,-0.035453912,0.028695842,7.852551E-34,0.024482865,-0.011550396,-0.045312665,-0.06499788,0.0013694816,0.0214954,-0.028953413,0.047516566,0.019773494,0.05389869,-0.011089388,-0.08905128,-0.017245846,-0.009029517,-0.04168663,0.044745862,0.099344134,-0.009499563,-0.009595888,0.11552693,0.07876855,-0.080956414,-0.115519576,0.09904684,-0.04161