.Africa. Share widely and freely. 31','a3c38d59354eaa9fbab7ca0a06d78b5091df54b62bee5a04def9ec8a45bf8770','Penal Code Act','General','[-0.019821469,0.060075328,-0.062064234,0.073198855,0.066072665,-0.012078029,0.019962428,-0.011247124,0.028674375,0.011889052,0.107762545,0.0014856555,0.07953514,-0.040183265,-0.014635546,-0.054169342,0.0069568506,-0.048914716,-0.055086885,0.07366423,0.017065518,-0.041004762,0.07549968,-0.015157588,-0.026721377,0.0075100837,0.06308644,0.009535078,-0.046273176,0.028767738,-0.012709572,0.0048493785,-0.0011990368,0.09279991,-0.0151722925,-0.03486067,-0.007876497,0.010594257,0.023293117,-0.008324912,-0.008272477,-0.035851736,-0.014475402,-0.006213352,0.0018894979,0.047517795,-0.11677306,0.05444273,-0.054718126,-0.08524867,-0.08971895,-0.013947318,0.048775516,0.13108267,-0.041991185,-0.049228095,-0.071978524,-0.006837465,0.007129948,-0.023894778,0.0015217379,0.03812634,0.01149585,-0.022503683,-0.021692898,0.027060265,-0.039341737,0.011425741,0.11944986,0.087707534,0.06265468,0.001962038,-0.09747507,0.03943331,0.022074085,-0.031436525,0.022599472,0.074156195,-0.020192618,-0.038802948,-0.038353436,0.014051071,0.0071728565,-0.08952366,-0.051193476,-0.02071418,0.0032740643,0.076380245,0.057566024,0.017423168,-0.02110426,-0.09307381,0.051126156,-0.09535581,0.027678473,0.024896443,-0.01298988,-0.08784844,-0.066503346,0.018629545,-0.061150294,0.03710346,-0.021348312,-0.011420724,0.038625497,0.04701753,0.020510351,-0.044831425,-0.03330406,0.008766226,0.010503694,-5.69258E-4,0.033162758,-0.029006045,0.05034475,0.04155919,0.0142855095,0.045751754,0.0474452,-0.09630393,-0.017361501,-0.0199589,0.053132217,0.0659666,-0.045962863,-0.119413994,-0.06798994,1.10463445E-33,-0.026800876,-0.010500497,-0.059008047,-0.0058385665,-0.028846253,0.006945797,-0.018756416,0.0035869887,0.071007624,0.085885726,0.030386353,-0.15401132,0.07997631,-0.026564904,0.017611375,0.0597144,0.07754758,0.054540418,-0.08525236,0.111938626,0.06408353,0.051004924,0.037628397,0.034531016