a court having jurisdiction in\nappeals from such a court or who are advocates of at least ten\nyears’ standing.\n(5) If the question of removing a judicial officer is referred to a\ntribun','5b61e676e218c67447284dbefc988bf1aeaf087d564b594fc8271fc20061ebe8','Uganda Constitution 1995','General','[-0.05022061,0.044262905,0.024503455,-0.01835936,-0.049683794,0.03342103,0.05615647,0.015820822,0.05442036,0.043266296,0.023328464,0.04287555,0.02012427,-0.07116501,-0.008733024,0.0011680867,0.054447446,0.012924225,-0.042007584,0.03782698,0.08043727,-0.01578762,-0.0704926,-0.03706352,-0.05306511,-0.098919086,-0.07786364,-0.028709749,-0.03598981,0.005303029,-0.01077519,-0.0067516193,-0.03702066,0.033794872,-0.0066975555,-0.04166776,0.049956203,0.011770469,0.036984205,-0.026548691,0.042790417,-0.006916877,-0.047873076,-0.059198584,0.027661053,0.033610083,-0.03039085,0.0027363608,-0.1450493,-0.06031683,-0.038403586,0.008810951,-0.038798872,0.08525255,-0.08563398,-0.041138727,-0.029739184,-0.040989958,0.0688387,0.033925794,-0.022143124,0.0068866573,0.014420878,0.04126406,0.030941712,-0.08652787,0.064202294,-0.11250653,0.06032079,0.0047091013,0.012438945,0.004032695,0.015738217,0.031143116,-0.10461891,0.036616202,0.044709153,0.05401343,0.05712551,-0.037471503,0.082322896,0.038172558,0.033756766,-0.037981357,-0.06762256,-0.04628449,-0.050114475,-0.06219163,-8.9789514E-4,-0.008413857,0.03223736,9.807282E-4,0.0442346,-0.043643452,0.032063354,-0.013989114,0.022647996,-0.0071345908,0.017055372,0.067583814,0.044319913,0.03581849,-0.032436527,0.026754377,-0.071766905,0.037499696,-0.083005086,-0.054242436,-0.013154629,-0.029811488,-0.046214692,-0.021742502,-0.027698582,-0.044927645,0.021364236,0.06503017,0.08651005,0.06844941,-0.036483005,-7.363701E-4,-0.04402554,0.024425002,-0.015250012,-0.035385367,0.021517528,0.0019560624,0.00797994,2.5864568E-33,-0.034249812,0.01704175,0.008072713,-0.08194736,0.02175193,0.060809296,-0.0031674472,0.0034137748,0.076834366,0.018155785,-0.054282844,-0.070